                        if (fieldMatch) {
                            currentField = { '内容': 'content', '图片': 'image', '时间': 'time', '点赞者': 'likes', '评论': 'commentsRaw' }[fieldMatch[1]];
                            post[currentField] = fieldMatch[2].trim();
                        } else if (currentField) {
                            post[currentField] += '\n' + trimmedLine;
                        }
                    }

                    const postAvatarHtml = isUser
