                    const isLikedByUser = post.likes.includes('[user]');
                    const cleanedLikes = post.likes.replace(/\[user\]/g, '').trim();
                    let likesText = cleanedLikes;
                    if (cleanedLikes) {
                        const likers = cleanedLikes.split(/,|，/);
                        if (likers.length > 6) { likesText = likers.slice(0, 5).join(', ') + ', ...'; }
                    }
                    const likesHtml = likesText ? `<div class="post-likes">♥ ${likesText}</div>` : '';

                    const commentRegex = /\[评论者\](.*?)\[\/评论者\](?:回复\[评论者\](.*?)\[\/评论者\])?说:\[(.*?)\]/gs;
